// YouTube channel RSS feeds for all 8 influencers
// UPDATE channel_id values if any are wrong
const influencers = [
  {
    name: 'Dan Martell',
    youtube_rss: 'https://www.youtube.com/feeds/videos.xml?channel_id=UCiNaJJQ5QmWxbj1InpGbmDg',
    twitter_rss: 'https://rss.app/feeds/YOUR_RSSAPP_KEY_DANMARTELL.xml',
    handle: '@DanMartell'
  },
  {
