    youtube_rss: 'https://www.youtube.com/feeds/videos.xml?channel_id=UCDuncanRogoff',
    twitter_rss: 'https://rss.app/feeds/YOUR_RSSAPP_KEY_DUNCAN.xml',
    handle: '@duncanrogoff'
  },
  {
    name: 'Tina Huang',
    youtube_rss: 'https://www.youtube.com/feeds/videos.xml?channel_id=UC2UXDak6o7rBm23x3jGpu3A',
    twitter_rss: 'https://rss.app/feeds/YOUR_RSSAPP_KEY_TINA.xml',
    handle: '@TinaHuang'
  },
  {
    name: 'Greg Eisenberg',
    youtube_rss: 'https://www.youtube.com/feeds/videos.xml?channel_id=UCGregEisenberg',
    twitter_rss: 'https://rss.app/feeds/YOUR_RSSAPP_KEY_GREG.xml',
    handle: '@GregEisenberg'
  },
  {
    name: 'Liam Ottley',
    youtube_rss: 'https://www.youtube.com/feeds/videos.xml?channel_id=UCo8bcnLyZH8tBIH9V1mLgqQ',
    twitter_rss: 'https://rss.app/feeds/YOUR_RSSAPP_KEY_LIAM.xml',
    handle: '@LiamOttley'
  },
  {
    name: 'Jeff Su',
    youtube_rss: 'https://www.youtube.com/feeds/videos.xml?channel_id=UCTedErMSNHFCg3g5HZK8i2Q',
    twitter_rss: 'https://rss.app/feeds/YOUR_RSSAPP_KEY_JEFFSU.xml',
    handle: '@JeffSu'
  }
];

return influencers.map(inf => ({ json: inf }));

// Parse XML RSS feeds and extract items from last 48 hours
const items = [];
const cutoff = Date.now() - (48 * 60 * 60 * 1000);

for (const input of $input.all()) {
  const body = input.json.data || input.json.body || '';
  if (!body) continue;

  // Extract entries from YouTube Atom feed
  const entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
  let match;
  while ((match = entryRegex.exec(body)) !== null) {
    const entry = match[1];
    const title = (entry.match(/<title>([^<]+)<\/title>/) || [])[1] || '';
    const link = (entry.match(/href="([^"]+)"/) || [])[1] || '';
    const published = (entry.match(/<published>([^<]+)<\/published>/) || [])[1] || '';
    const description = (entry.match(/<media:description>([\s\S]*?)<\/media:description>/) || [])[1] || '';

    const pubTime = published ? new Date(published).getTime() : 0;
    if (pubTime > cutoff && title) {
      items.push({
        source: 'YouTube',
        title: title.trim(),
        link,
        published,
        description: description.substring(0, 300).trim()
      });
    }
  }

  // Extract items from Twitter RSS (RSS 2.0 format)
  const itemRegex = /<item>([\s\S]*?)<\/item>/g;
  while ((match = itemRegex.exec(body)) !== null) {
    const item = match[1];
    const title = (item.match(/<title><!\[CDATA\[([^\]]+)\]\]><\/title>/) || item.match(/<title>([^<]+)<\/title>/) || [])[1] || '';
    const link = (item.match(/<link>([^<]+)<\/link>/) || [])[1] || '';
    const pubDate = (item.match(/<pubDate>([^<]+)<\/pubDate>/) || [])[1] || '';

    const pubTime = pubDate ? new Date(pubDate).getTime() : 0;
    if (pubTime > cutoff && title) {
      items.push({
        source: 'Twitter',
        title: title.trim(),
        link,
        published: pubDate
      });
    }
  }
}

if (items.length === 0) {
  items.push({ source: 'fallback', title: 'No new content in last 48h', link: '', published: new Date().toISOString() });
}

return [{ json: { items, count: items.length } }];

// Merge all influencer content into one prompt
const allItems = [];
for (const input of $input.all()) {
  if (input.json.items) {
    allItems.push(...input.json.items);
  }
}

// Format for AI prompt
const contentList = allItems
  .filter(i => i.title && i.title !== 'No new content in last 48h')
  .slice(0, 30) // max 30 items
  .map((item, i) => `${i+1}. [${item.source}] ${item.title}${item.link ? ' — ' + item.link : ''}`)
  .join('\n');

const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Ho_Chi_Minh' });

return [{ json: { contentList, today, totalItems: allItems.length } }];

const aiResponse = $input.first().json.message?.content || $input.first().json.choices?.[0]?.message?.content || 'No response';
const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

// Split into chunks for Telegram (max 4096 chars)
const header = `🤖 *AI Daily Brief — ${today}*\n━━━━━━━━━━━━━━━━━━━━\n\n`;
const fullMessage = header + aiResponse;

// Telegram has 4096 char limit — split if needed
const chunks = [];
let remaining = fullMessage;
while (remaining.length > 0) {
  chunks.push(remaining.substring(0, 4000));
  remaining = remaining.substring(4000);
}

return chunks.map(chunk => ({ json: { text: chunk } }));
